import{_ as d,o as i,c as t,ag as s}from"./chunks/framework.DHSXpJLs.js";const k=JSON.parse('{"title":"IFC 编辑服务（services/ifc）","description":"","frontmatter":{},"headers":[],"relativePath":"development/edit-service.md","filePath":"development/edit-service.md","lastUpdated":1790781261000}'),a={name:"development/edit-service.md"};function o(c,e,r,l,n,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="ifc-编辑服务-services-ifc" tabindex="-1">IFC 编辑服务（services/ifc） <a class="header-anchor" href="#ifc-编辑服务-services-ifc" aria-label="Permalink to &quot;IFC 编辑服务（services/ifc）&quot;">​</a></h1><p><code>services/ifc/</code> 是 Python FastAPI 服务，基于 ifcopenshell 和 ifcdiff，默认端口 8100。它提供 IFC 脚本沙箱执行、版本快照、ScriptMap 定位和语义 diff。原 L1 直改链路已退役。DXF 侧的同构服务见 <a href="/SourceAEC/development/cad-service">CAD 编辑服务</a>。</p><h2 id="运行与配置" tabindex="-1">运行与配置 <a class="header-anchor" href="#运行与配置" aria-label="Permalink to &quot;运行与配置&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> services/ifc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VIEWER_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">realpath</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../data)&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uvicorn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.main:app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8100</span></span></code></pre></div><p>依赖全部来自 PyPI 官方发布，<code>uv sync</code> 直接安装。环境变量（<code>VIEWER_DATA_DIR</code>、<code>EDIT_SERVICE_PORT</code>、<code>AIIFC_FLOWS_DIR</code>、<code>EDIT_SERVICE_MAX_MODELS</code> 等）与沙箱变量集中在<a href="/SourceAEC/guide/configuration">配置说明</a>，沙箱机制见<a href="/SourceAEC/development/sandbox">沙箱执行环境</a>。</p><h2 id="端点" tabindex="-1">端点 <a class="header-anchor" href="#端点" aria-label="Permalink to &quot;端点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>端点</th><th>契约</th></tr></thead><tbody><tr><td>脚本编辑</td><td><code>GET/PUT /models/{id}/script</code>、<code>script/params</code>、<code>script/undo|redo|discard</code></td><td><a href="/SourceAEC/reference/edit-api">IFC 编辑 API</a></td></tr><tr><td>沙箱与版本</td><td><code>POST /models/{id}/script/run</code>、<code>save</code>、<code>rollback</code></td><td>同上</td></tr><tr><td>版本与对比</td><td><code>GET /models/{id}/scripts</code>、<code>POST .../script/diff</code>、<code>GET .../script/staging/diff</code></td><td>同上</td></tr><tr><td>定位与改写</td><td><code>GET /models/{id}/script/locate?guid=</code>、<code>POST .../script/edit-call</code></td><td>同上</td></tr><tr><td>语义 diff</td><td><code>GET /models/{id}/versions</code>、<code>POST /models/{id}/diff</code>、<code>.../diff/upload</code></td><td>同上</td></tr><tr><td>运行簿记</td><td><code>GET/DELETE /models/{id}/pending</code>、<code>GET /models/{id}/history</code></td><td>同上的「版本与语义对比」</td></tr><tr><td>外部修改登记</td><td><code>POST /models/{id}/user-edits</code></td><td>同上</td></tr><tr><td>直改遗产</td><td><code>PUT/DELETE /models/{id}/entities/{guid}</code>、<code>POST /models/{id}/commit</code></td><td><strong>已退役</strong>，直连返回 410</td></tr></tbody></table><p><code>pending</code> 在直改退役后只作运行簿记；<code>history</code> 只读保留，新记录来自外部修改登记。</p><h2 id="实现要点" tabindex="-1">实现要点 <a class="header-anchor" href="#实现要点" aria-label="Permalink to &quot;实现要点&quot;">​</a></h2><ul><li>沙箱执行、暂存、版本、diff 这些领域逻辑的单一事实源在共享包 <code>aibim_sandbox</code>，REST 编辑面在 <code>aibim_editapi</code>，本服务只留薄适配层，详见<a href="/SourceAEC/development/sandbox">沙箱执行环境</a>。</li><li><code>app/ifc_materialize.py</code> 负责按需重建历史版本 IFC，结果进 LRU 缓存。重建产物只保证语义相等，比较一律走 diff。</li><li><code>app/route_common.py</code> 统一请求解析；业务校验住在各 <code>verify*</code> 函数里，这是仓库 <code>AGENTS.md</code> 的硬规则。</li><li><code>app/registry.py</code> 做模型缓存、原子保存和每路径文件锁。</li><li><code>app/diffing.py</code> 适配 IfcDiff：只比较属性和属性集，changed 的字段级明细自算，快照间结果缓存。</li></ul><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> services/ifc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span></code></pre></div><h2 id="独立部署与移植" tabindex="-1">独立部署与移植 <a class="header-anchor" href="#独立部署与移植" aria-label="Permalink to &quot;独立部署与移植&quot;">​</a></h2><p>这个服务可以脱离 Go server、web、converter、PostgreSQL 单独部署，也可以整体搬到新宿主。它是和 aiifc skill 配对的服务端：skill 产出脚本，它负责执行、存版本和算 diff。</p><p>移植的最小步骤：</p><ol><li>拷贝 <code>services/ifc/</code> 和 <code>skills/aiifc/</code>，沙箱执行需要后者 flows 里的 <code>script_lib.py</code>。</li><li>在 <code>services/ifc/</code> 下执行 <code>uv sync</code>。</li><li>把 <code>VIEWER_DATA_DIR</code> 配成绝对路径，指向你的模型数据根目录。</li><li>启动服务，打开 <code>/docs</code> 的 Swagger UI 自检。</li></ol><p>其他组件都是可缺省的：</p><table tabindex="0"><thead><tr><th>缺少的组件</th><th>还能做什么</th><th>少了什么</th></tr></thead><tbody><tr><td>Go server</td><td>全部编辑、diff、版本端点直连可用</td><td>统一 envelope、对外入口、鉴权、XKT 重转、浏览器桥接</td></tr><tr><td>web</td><td>纯 API 调用不受影响</td><td>可视化界面</td></tr><tr><td>converter</td><td>编辑与 diff 完全可用</td><td>IFC 转 XKT 的渲染链路</td></tr><tr><td>PostgreSQL</td><td>默认文件存储即可</td><td>Issue 等数据的 PG 持久化</td></tr></tbody></table><p>数据约定只有一条：任何组件按同一个 <code>VIEWER_DATA_DIR</code> 写 <code>uploads/{id}.ifc</code>，编辑服务就能使用它。</p><p>两点边界要注意。8100 直连没有鉴权，务必只监听 127.0.0.1，要对外请走 Go server。provenance 的 <code>UI</code>、<code>AI</code>、<code>USER</code> 是调用方自报的声明字段，服务端只校验枚举，语义见<a href="/SourceAEC/reference/api-model">模型与审查 API</a>。</p>`,20)])])}const f=d(a,[["render",o]]);export{k as __pageData,f as default};
